namespace KumikoUI.Core.Models;

/// <summary>
/// Whether the grid builds columns from the properties of its items (the host's <c>AutoGenerateColumns</c>).
/// </summary>
/// <remarks>
/// The item type is the run-time type of the first non-null item. Generated columns are added to the grid's
/// <c>Columns</c> collection with <see cref="KumikoColumn.IsAutoGenerated"/> set, so the app, layout state and the
/// column chooser see them like declared ones. See <see cref="KumikoColumnFactory"/> for how a property maps to a column.
/// </remarks>
public enum KumikoAutoGenerateColumnsMode
{
    /// <summary>No columns are generated; only declared columns are shown. The default.</summary>
    None,

    /// <summary>Columns are generated only when no column is declared.</summary>
    Auto,

    /// <summary>
    /// Declared columns are kept, and a column is generated, after them, for every property that no declared column
    /// binds (by <see cref="KumikoColumn.PropertyName"/>, ignoring case).
    /// </summary>
    Merge,
}
